const fs=require('fs'),{PGlite}=require('@electric-sql/pglite');
const base=require('./dictionaryExchangeDatabase.cjs'),{workspaceDatabase}=require('./workspaceDatabase.cjs'),{applyDictionaryRetention}=require('./dictionaryRetention.cjs');
const names={official:'20261105091439_official_card_linked_content.sql',ipa:'20261105091518_dictionary_pronunciation_columns_retired.sql',page:'20261105091519_page_study_items_retired.sql'};
async function database(){const pg=new PGlite();await workspaceDatabase(pg);await pg.exec('alter table pages drop column official_pack_id,drop column official_pack_version');for(const f of [...base.dictionaryMigrations,'20261016060000_dictionary_retire_verification_state.sql','20261017010000_dictionary_core_concept.sql','20261009_official_study_packs.sql','20261015_official_private_card_edit.sql','20261016030000_official_private_card_identity.sql'])await pg.exec(fs.readFileSync('supabase/migrations/'+f,'utf8'));await applyDictionaryRetention(pg);await pg.exec('reset role');for(const f of ['20261016_study_reliability.sql','20261105032115_study_deck_clear.sql','20261105065440_dictionary_word_segments.sql'])await pg.exec(fs.readFileSync('supabase/migrations/'+f,'utf8'));await pg.query('insert into auth.users values($1),($2)',[base.owner,base.id(900001)]);await pg.query('insert into dictionary_admins values($1)',[base.owner]);await pg.query("select set_config('request.jwt.claim.sub',$1,false)",[base.owner]);await pg.exec('set role authenticated');return pg;}
async function migrate(pg,key){await pg.exec('reset role');await pg.exec(fs.readFileSync('supabase/migrations/'+names[key],'utf8'));await pg.exec('set role authenticated');}
module.exports={...base,database,migrate,names};
